  Object.assign(state,{fsLevel:0,fsCustom:1});
  const fsStrings=__FONT_SETTINGS_TEXTS__,fsLevels=[[-3,'ExtraSmall',.8],[-2,'VerySmall',.86],[-1,'Small',.92],[0,'Standard',1],[1,'Large',1.08],[2,'Big',1.16],[3,'VeryBig',1.24],[4,'ExtraBig',1.32]];
  function fsT(key,values={}){let value=fsStrings[key]||key;for(const [k,v] of Object.entries(values))value=value.replaceAll('{'+k+'}',v);return value;}
  function fsCustom(){return Math.abs(state.fsCustom-1)>.01;}
  function fsEffective(){return fsCustom()?state.fsCustom:fsLevels.find(([level])=>level===state.fsLevel)?.[2]||1;}
  function fsName(){return fsCustom()?fsT('fontSettingsCustomAdjust'):fsT('fontSettings'+fsLevels.find(([level])=>level===state.fsLevel)[1]);}
  function fsInfo(){const eff=fsEffective().toFixed(2),width=qPreview.width-2;return [[fsT('fontSettingsScreenDensity'),'3.00'],[fsT('fontSettingsScreenWidth'),width+'dp'],[fsT('fontSettingsDeviceScale'),'x1.00'],[fsT('fontSettingsUserScale'),'x'+eff],[fsT('fontSettingsFinalScale'),'x'+eff],[fsT('fontSettingsBaseDevice'),Math.abs(width-407)/407<.05?fsT('fontSettingsYes'):fsT('fontSettingsNo')],[fsT('fontSettingsRecommendedScale'),'x1.00']];}
  function fsBody(){const eff=fsEffective().toFixed(2),sample=(key,value,size)=>`<div class="fs-sample"><small>${fsT(key)}</small><span style="--fs-font:${size}px;font-weight:${[20,16,18].includes(size)?600:400}">${value}</span></div>`;return `<div class="fs-page"><p class="bc-small" data-fs-current>${fsT('fontSettingsCurrentScale',{scale:eff})}</p>${surface(`<h3>${fsT('fontSettingsPreview')}</h3><p class="fs-body-preview">${esc(fsT('fontSettingsPreviewText'))}</p><p class="bc-small" data-fs-caption>${fsT('fontSettingsCurrentLevel',{level:fsName(),scale:eff})}</p><hr><h4>${fsT('fontSettingsMoreStyles')}</h4>${sample('fontSettingsPageTitle','月度统计与分析',20)}${sample('fontSettingsBlockTitle','最近记账',16)}${sample('fontSettingsBodyExample','今天早餐：豆浆 + 包子 6.50 元',14)}${sample('fontSettingsLabelExample','隐藏金额已开启',11)}${sample('fontSettingsStrongNumber','1234.56',18)}<hr><div class="fs-list-preview">${icon('palette')}<div><b>${fsT('fontSettingsListTitle')}</b><small>${fsT('fontSettingsListSubtitle')}</small></div><strong>123.45</strong></div>`)}${surface(`<h3>${fsT('fontSettingsQuickLevel')}</h3><div class="fs-levels">${fsLevels.map(([level,key])=>btn('fs-level:'+level,`${!fsCustom()&&state.fsLevel===level?icon('check'):''}${fsT('fontSettings'+key)}`,fsT('fontSettings'+key),'v4-chip',`aria-pressed="${!fsCustom()&&state.fsLevel===level}" data-selected="${!fsCustom()&&state.fsLevel===level}"`)).join('')}</div>`)}${surface(`<h3>${fsT('fontSettingsCustomAdjust')}</h3><div class="fs-slider-label"><span>${fsT('fontSettingsPreciseAdjust')}</span><output data-fs-value>x${eff}</output></div><input class="v4-range" type="range" min="0.7" max="1.5" step="0.01" value="${state.fsCustom}" data-fs-custom aria-label="${fsT('fontSettingsPreciseAdjust')}"><div class="fs-ticks"><span>0.7x</span><span>1.0x</span><span>1.5x</span></div><div class="fs-actions">${btn('fs-reset',fsT('fontSettingsResetTo1x'),fsT('fontSettingsResetTo1x'),'bc-secondary')}${btn('fs-adapt',fsT('fontSettingsAdaptBase'),fsT('fontSettingsAdaptBase'),'bc-secondary')}</div>`)}${surface(`<details class="fs-device"><summary>${fsT('fontSettingsScreenInfo')}${icon('chevron-down')}</summary><div>${fsInfo().map(([label,value])=>`<div class="fs-info-row"><span>${label}</span><b data-fs-info="${label}">${value}</b></div>`).join('')}<div class="fs-device-example"><i></i><small>${fsT('fontSettingsScaleExample')}</small></div></div></details>`)}<p class="bc-small fs-description">${fsT('fontSettingsDescription')}</p></div>`;}
  fDefs.font.body=fsBody;fDefs.font.title=fsT('mineDisplayScale');
  const fsPreviousRender=fRender;fRender=function(key){if(key!=='font')return fsPreviousRender(key);return `<div class="bc-subhead"><div class="bc-heading-left">${btn('back',icon('chevron-left'),'返回')}<h2>${fsT('mineDisplayScale')}</h2></div></div><div class="fs-shell"><div class="fs-scroll">${fsBody()}</div></div>`;};
  function fsApply(){if(!phone.querySelector('.fs-page'))return;phone.style.setProperty('--q-scale',qPreview.scale*fsEffective());phone.dataset.fsStacked=String(qPreview.width-68<300&&qPreview.scale*fsEffective()*14>18);const eff=fsEffective().toFixed(2);phone.querySelector('[data-fs-custom]').style.setProperty('--v4-value',((state.fsCustom-.7)/.8*100)+'%');phone.querySelector('[data-fs-current]').textContent=fsT('fontSettingsCurrentScale',{scale:eff});phone.querySelector('[data-fs-caption]').textContent=fsT('fontSettingsCurrentLevel',{level:fsName(),scale:eff});phone.querySelector('[data-fs-value]').textContent='x'+eff;for(const [label,value]of fsInfo())phone.querySelector('[data-fs-info="'+label+'"]').textContent=value;phone.querySelector('.fs-device-example').style.setProperty('--fs-example',24*fsEffective()*(.8+.2*(qPreview.width-2)/407)+'px');for(const el of phone.querySelectorAll('[data-action^="fs-level:"]')){const on=!fsCustom()&&Number(el.dataset.action.split(':')[1])===state.fsLevel;el.setAttribute('aria-pressed',on);el.dataset.selected=on;const check=el.querySelector('svg');if(check)check.style.display=on?'':'none';else if(on){el.insertAdjacentHTML('afterbegin',icon('check'));if(globalThis.lucide)lucide.createIcons();}}}
  const fsPreviousAfter=qAfterRender;qAfterRender=function(){fsPreviousAfter();fsApply();};
  function fsDraw(){const scroll=phone.querySelector('.fs-scroll').scrollTop;render();phone.querySelector('.fs-scroll').scrollTop=scroll;persist();}
  root.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el?.dataset.action.startsWith('fs-'))return;event.preventDefault();event.stopImmediatePropagation();if(el.dataset.action.startsWith('fs-level:')){state.fsLevel=Number(el.dataset.action.split(':')[1]);state.fsCustom=1;}else{state.fsLevel=0;state.fsCustom=1;}fsDraw();},true);
  root.addEventListener('input',event=>{if(!event.target.matches('[data-fs-custom]'))return;state.fsCustom=Number(event.target.value);state.fsLevel=0;fsApply();persist();},true);
  root.addEventListener('change',event=>{if(event.target.matches('[data-fs-custom]'))fsDraw();},true);
